SELECT
  SUM(STORE_COUNT)           AS storeCount,
  SUM(OPENING_STORE_COUNT)   AS openingStoreCount,
  SUM(CLOSURE_STORE_COUNT)   AS closureStoreCount,
  SUM(FRANCHISE_STORE_COUNT) AS franchiseStoreCount
FROM STORE
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND SERVICE_INDUSTRY_CODE  = #{serviceIndustryCode}
  AND BASE_YEAR_QUARTER_CODE = #{yearQuarter}

SELECT
  SUM(STORE_COUNT)           AS storeCount,
  SUM(OPENING_STORE_COUNT)   AS openingStoreCount,
  SUM(CLOSURE_STORE_COUNT)   AS closureStoreCount,
  SUM(FRANCHISE_STORE_COUNT) AS franchiseStoreCount
FROM STORE
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND SERVICE_INDUSTRY_CODE  = #{serviceIndustryCode}
  AND BASE_YEAR_QUARTER_CODE = (
  SELECT MAX(BASE_YEAR_QUARTER_CODE)
  FROM STORE
  WHERE ADMIN_DONG_CODE        = #{adminDongCode}
    AND SERVICE_INDUSTRY_CODE  = #{serviceIndustryCode}
    AND BASE_YEAR_QUARTER_CODE < #{yearQuarter}
)

SELECT
  AVG(OPERATING_BUSINESS_MONTH_AVG) AS avgOperatingMonths
FROM COMMERCIAL_CHANGE_INDICATOR
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND BASE_YEAR_QUARTER_CODE = #{yearQuarter}

SELECT TOTAL_FLOATING_POPULATION AS totalFloatingPopulation
FROM STREET_POPULATION
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND BASE_YEAR_QUARTER_CODE = (
  SELECT MAX(BASE_YEAR_QUARTER_CODE)
  FROM STREET_POPULATION
  WHERE ADMIN_DONG_CODE        = #{adminDongCode}
    AND BASE_YEAR_QUARTER_CODE < #{yearQuarter}
)

SELECT
  TOTAL_RESIDENT_POPULATION AS totalResidentPopulation,
  TOTAL_HOUSEHOLD_COUNT     AS totalHouseholdCount
FROM RESIDENT_POPULATION
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND BASE_YEAR_QUARTER_CODE = (
  SELECT MAX(BASE_YEAR_QUARTER_CODE)
  FROM RESIDENT_POPULATION
  WHERE ADMIN_DONG_CODE        = #{adminDongCode}
    AND BASE_YEAR_QUARTER_CODE < #{yearQuarter}
)

SELECT
  TOTAL_RESIDENT_POPULATION AS totalResidentPopulation,
  TOTAL_HOUSEHOLD_COUNT     AS totalHouseholdCount
FROM RESIDENT_POPULATION
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND BASE_YEAR_QUARTER_CODE = #{yearQuarter}

SELECT
  TOTAL_RESIDENT_POPULATION AS totalResidentPopulation,
  TOTAL_HOUSEHOLD_COUNT     AS totalHouseholdCount
FROM RESIDENT_POPULATION
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND BASE_YEAR_QUARTER_CODE = (
  SELECT MAX(BASE_YEAR_QUARTER_CODE)
  FROM RESIDENT_POPULATION
  WHERE ADMIN_DONG_CODE        = #{adminDongCode}
    AND BASE_YEAR_QUARTER_CODE < #{yearQuarter}
)

SELECT TOTAL_WORKER_POPULATION AS totalWorkerPopulation
FROM WORKER_POPULATION
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND BASE_YEAR_QUARTER_CODE = (
  SELECT MAX(BASE_YEAR_QUARTER_CODE)
  FROM WORKER_POPULATION
  WHERE ADMIN_DONG_CODE        = #{adminDongCode}
    AND BASE_YEAR_QUARTER_CODE < #{yearQuarter}
)

SELECT
  MONTHLY_SALES_AMOUNT AS monthlySalesAmount,
  MONTHLY_SALES_COUNT  AS monthlySalesCount
FROM ESTIMATED_SALES
WHERE ADMIN_DONG_CODE        = #{adminDongCode}
  AND SERVICE_INDUSTRY_CODE  = #{serviceIndustryCode}
  AND BASE_YEAR_QUARTER_CODE = (
  SELECT MAX(BASE_YEAR_QUARTER_CODE)
  FROM ESTIMATED_SALES
  WHERE ADMIN_DONG_CODE        = #{adminDongCode}
    AND SERVICE_INDUSTRY_CODE  = #{serviceIndustryCode}
    AND BASE_YEAR_QUARTER_CODE < #{yearQuarter}
)

SELECT
  SALES_CHANGE_RATE           AS salesChangeRate,
  SALES_TO_INDUSTRY_AVG_RATIO AS salesToIndustryAvgRatio,
  SALES_PER_STORE             AS salesPerStore
FROM REPORT_DATA_SALES
WHERE ADMIN_DONG_CODE       = #{adminDongCode}
  AND SERVICE_INDUSTRY_CODE = #{serviceIndustryCode}
  AND BASE_YEAR_QUARTER_CODE = #{yearQuarter}
